"use client";

import { useMemo, useState } from "react";
import { CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleMinus, Clock3, Download, FileText, Filter, MapPin, Pencil, RefreshCw, Search, Settings, UserRound, UsersRound, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import type { AdminDailyAttendanceRecord, AdminLeavePayload, AdminLeaveRequestRecord, AdminMonthlyAttendancePayload, AttendanceDayStatus, AttendanceStaffUser } from "@/lib/attendance/queries";
import type { AttendanceGeofenceSettingsPayload } from "@/lib/attendance/geofence";
import type { AttendanceLateRulePayload } from "@/lib/attendance/late-rule";
import { cn } from "@/lib/utils/cn";

type ApiResponse = { success: boolean; data?: unknown; error?: { message?: string } };
type Notice = { tone: "success" | "error"; text: string };
type AttendanceView = "daily" | "monthly" | "leave";
type GridStatus = AttendanceDayStatus | "weekend_off";

interface AttendanceAdminDeskProps {
  initialDailyDateKey: string;
  initialDailyRecords: AdminDailyAttendanceRecord[];
  initialLeaveData: AdminLeavePayload;
  initialMonthKey: string;
  initialMonthlyData: AdminMonthlyAttendancePayload;
  initialGeofenceSettings: AttendanceGeofenceSettingsPayload | null;
  initialLateRule: AttendanceLateRulePayload | null;
  staffUsers: AttendanceStaffUser[];
}

const panel = "rounded-lg border border-vega-border bg-vega-surface-1";
const select = "h-[38px] w-full rounded-md border border-vega-border bg-[#0b141f] px-3 text-xs text-vega-text outline-none focus:border-vega-accent/70";
const parseDate = (key: string) => new Date(`${key}T00:00:00`);

function dateLabel(key?: string, long = false) {
  if (!key) return "--";
  return parseDate(key).toLocaleDateString("en-IN", { weekday: long ? "long" : undefined, day: long ? "numeric" : "2-digit", month: long ? "long" : "short", year: "numeric" });
}
function shortDate(key?: string) {
  if (!key) return "--";
  return parseDate(key).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" });
}
function timeLabel(value?: string | null) {
  return value ? new Date(value).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }) : "--";
}
function monthLabel(key?: string) {
  return key && /^\d{4}-\d{2}$/.test(key) ? parseDate(`${key}-01`).toLocaleDateString("en-IN", { month: "long", year: "numeric" }) : "--";
}
function workLabel(minutes = 0) {
  return minutes > 0 ? `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m` : "--";
}
function shiftDate(key: string, amount: number) {
  const value = parseDate(key); value.setDate(value.getDate() + amount);
  return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;
}
function shiftMonth(key: string, amount: number) {
  const value = parseDate(`${key}-01`); value.setMonth(value.getMonth() + amount);
  return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}`;
}
function monthDates(key: string) {
  if (!/^\d{4}-\d{2}$/.test(key)) return [];
  const [year, month] = key.split("-").map(Number);
  return Array.from({ length: new Date(year, month, 0).getDate() }, (_, index) => `${key}-${String(index + 1).padStart(2, "0")}`);
}
function isWeekend(key: string) { const day = parseDate(key).getDay(); return day === 0 || day === 6; }
function initials(name: string) { return name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase(); }
function titleCase(value: string) { return value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase()); }
function statusSymbol(status?: GridStatus) { return status === "present" ? "P" : status === "absent" ? "A" : status === "half_day" ? "H" : status === "late_coming" ? "L" : status === "weekend_off" ? "W" : "-"; }
function statusClass(status?: GridStatus) {
  if (status === "present") return "bg-vega-green-soft text-[#66dc91]";
  if (status === "absent") return "bg-vega-red-soft text-vega-red";
  if (status === "half_day") return "bg-vega-yellow-soft text-vega-yellow";
  if (status === "late_coming") return "bg-vega-accent-soft text-[#b794f8]";
  if (status === "weekend_off") return "bg-[#17273a] text-[#b7c7df]";
  return "text-vega-text-muted";
}
function attendanceBadge(status?: AttendanceDayStatus) {
  if (status === "present") return { label: "Present", variant: "success" as const };
  if (status === "absent") return { label: "Absent", variant: "danger" as const };
  if (status === "half_day") return { label: "Half day", variant: "warning" as const };
  if (status === "late_coming") return { label: "Late", variant: "accent" as const };
  return { label: "Not marked", variant: "neutral" as const };
}
// The single at-a-glance verdict for a whole month, combining lateness and absence - the two
// things that actually need attention. Present/half-day counts stay as plain numbers elsewhere;
// they don't need a severity badge because they aren't a problem to flag.
function monthlyStatusBadge(summary: { lateComingDays: number; absentDays: number }) {
  const parts: string[] = [];
  if (summary.absentDays > 0) parts.push(`${summary.absentDays} Absent`);
  if (summary.lateComingDays > 0) parts.push(`${summary.lateComingDays} Late`);
  if (parts.length === 0) return { label: "On time", variant: "success" as const };
  return { label: parts.join(", "), variant: summary.absentDays > 0 ? ("danger" as const) : ("warning" as const) };
}
function leaveBadge(status: AdminLeaveRequestRecord["status"]) {
  if (status === "approved") return { label: "Approved", variant: "success" as const };
  if (status === "pending") return { label: "Pending", variant: "warning" as const };
  if (status === "rejected") return { label: "Rejected", variant: "danger" as const };
  return { label: "Cancelled", variant: "neutral" as const };
}

function Avatar({ name, index = 0, large = false }: { name: string; index?: number; large?: boolean }) {
  const colors = ["bg-[#4338a5]", "bg-[#2563a8]", "bg-[#147a6b]", "bg-[#8b3f75]", "bg-[#8a6423]"];
  return <span className={cn("inline-flex shrink-0 items-center justify-center rounded-full font-semibold text-white", colors[index % colors.length], large ? "h-11 w-11 text-sm" : "h-8 w-8 text-[11px]")}>{initials(name)}</span>;
}
function Metric({ icon: Icon, label, value, tone = "blue" }: { icon: typeof UsersRound; label: string; value: number; tone?: "blue" | "green" | "purple" | "red" | "neutral" }) {
  const color = { blue: "bg-vega-blue-soft text-[#5da2ff]", green: "bg-vega-green-soft text-[#55df89]", purple: "bg-vega-accent-soft text-[#a875ff]", red: "bg-vega-red-soft text-[#ff6872]", neutral: "bg-[#172536] text-[#b8c8dc]" }[tone];
  return <div className={cn(panel, "flex min-h-[74px] items-center gap-3 px-4 py-3")}><span className={cn("inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full", color)}><Icon className="h-5 w-5" strokeWidth={1.8} /></span><div><p className="text-[11px] text-vega-text-muted">{label}</p><p className="mt-0.5 text-xl font-semibold leading-none text-vega-text">{value}</p></div></div>;
}

export function AttendanceAdminDesk({ initialDailyDateKey, initialDailyRecords, initialLeaveData, initialMonthKey, initialMonthlyData, initialGeofenceSettings, initialLateRule, staffUsers }: AttendanceAdminDeskProps) {
  const [activeView, setActiveView] = useState<AttendanceView>("daily");
  const [dailyDateKey, setDailyDateKey] = useState(initialDailyDateKey);
  const [dailyRecords, setDailyRecords] = useState(initialDailyRecords);
  const [leaveData, setLeaveData] = useState(initialLeaveData);
  const [monthKey, setMonthKey] = useState(initialMonthKey);
  const [monthlyData, setMonthlyData] = useState(initialMonthlyData);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [loadingKey, setLoadingKey] = useState<string | null>(null);
  const [dailySearch, setDailySearch] = useState("");
  const [dailyStatus, setDailyStatus] = useState("all");
  const [leaveSearch, setLeaveSearch] = useState("");
  const [leaveStatus, setLeaveStatus] = useState("all");
  const [leaveType, setLeaveType] = useState("all");
  const [selectedLeaveId, setSelectedLeaveId] = useState(initialLeaveData.requests[0]?._id ?? "");
  const [visibleLeaveCount, setVisibleLeaveCount] = useState(4);
  const [reviewNotes, setReviewNotes] = useState<Record<string, string>>({});
  const [selectedMonthlyUserId, setSelectedMonthlyUserId] = useState(initialMonthlyData.rows[0]?.user._id ?? "");
  const [selectedMonthDateKey, setSelectedMonthDateKey] = useState(initialDailyDateKey.startsWith(initialMonthKey) ? initialDailyDateKey : `${initialMonthKey}-01`);
  const [mobileMarkOpen, setMobileMarkOpen] = useState(false);
  const [officeSettingsOpen, setOfficeSettingsOpen] = useState(false);
  const [geofenceForm, setGeofenceForm] = useState({ officeLatitude: initialGeofenceSettings?.officeLatitude?.toString() ?? "", officeLongitude: initialGeofenceSettings?.officeLongitude?.toString() ?? "", officeRadiusMeters: (initialGeofenceSettings?.officeRadiusMeters ?? 200).toString() });
  const [lateRuleSettingsOpen, setLateRuleSettingsOpen] = useState(false);
  const [lateRuleForm, setLateRuleForm] = useState({ shiftStartTime: initialLateRule?.shiftStartTime ?? "10:00", lateGraceMinutes: (initialLateRule?.lateGraceMinutes ?? 15).toString() });
  const [lateRuleConfigured, setLateRuleConfigured] = useState(Boolean(initialLateRule));
  const [markForm, setMarkForm] = useState({ userId: staffUsers[0]?._id ?? "", dateKey: initialDailyDateKey, dayStatus: "present" as AttendanceDayStatus });

  async function loadDaily(dateKey: string) {
    const response = await fetch(`/api/attendance/admin/daily?dateKey=${dateKey}`, { cache: "no-store" });
    const payload = (await response.json()) as ApiResponse;
    if (!response.ok || !payload.success || !payload.data) throw new Error(payload.error?.message ?? "Unable to load daily attendance.");
    const parsed = payload.data as { dateKey: string; records: AdminDailyAttendanceRecord[] };
    setDailyDateKey(parsed.dateKey); setDailyRecords(parsed.records);
  }
  async function loadMonth(nextMonth: string) {
    const response = await fetch(`/api/attendance/admin/month?month=${nextMonth}`, { cache: "no-store" });
    const payload = (await response.json()) as ApiResponse;
    if (!response.ok || !payload.success || !payload.data) throw new Error(payload.error?.message ?? "Unable to load monthly attendance.");
    const parsed = payload.data as AdminMonthlyAttendancePayload;
    setMonthKey(parsed.monthKey); setMonthlyData(parsed); setSelectedMonthDateKey(`${parsed.monthKey}-01`);
    setSelectedMonthlyUserId((current) => parsed.rows.some((row) => row.user._id === current) ? current : (parsed.rows[0]?.user._id ?? ""));
  }
  async function loadLeave() {
    const response = await fetch("/api/attendance/admin/leave", { cache: "no-store" });
    const payload = (await response.json()) as ApiResponse;
    if (!response.ok || !payload.success || !payload.data) throw new Error(payload.error?.message ?? "Unable to load leave requests.");
    const parsed = payload.data as AdminLeavePayload; setLeaveData(parsed);
    setSelectedLeaveId((current) => parsed.requests.some((request) => request._id === current) ? current : (parsed.requests[0]?._id ?? ""));
  }
  async function runAction(key: string, path: string, method: "PATCH" | "POST", successText: string, options?: { body?: Record<string, unknown>; refreshDaily?: boolean; refreshDate?: string; refreshMonthly?: boolean; refreshMonth?: string; onSuccess?: () => void }) {
    setLoadingKey(key); setNotice(null);
    try {
      const response = await fetch(path, { method, headers: options?.body ? { "Content-Type": "application/json" } : undefined, body: options?.body ? JSON.stringify(options.body) : undefined });
      const payload = (await response.json()) as ApiResponse;
      if (!response.ok || !payload.success) throw new Error(payload.error?.message ?? "Unable to complete action.");
      if (options?.refreshDaily) await loadDaily(options.refreshDate ?? dailyDateKey);
      if (options?.refreshMonthly) await loadMonth(options.refreshMonth ?? monthKey);
      options?.onSuccess?.(); setNotice({ tone: "success", text: successText });
    } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Unable to complete action." }); }
    finally { setLoadingKey(null); }
  }
  async function refreshDaily(key = dailyDateKey) { setLoadingKey("daily-refresh"); setNotice(null); try { await loadDaily(key); } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Unable to load daily attendance." }); } finally { setLoadingKey(null); } }
  async function refreshMonth(key = monthKey) { setLoadingKey("month-refresh"); setNotice(null); try { await loadMonth(key); } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Unable to load monthly attendance." }); } finally { setLoadingKey(null); } }
  async function refreshLeave() { setLoadingKey("leave-refresh"); setNotice(null); try { await loadLeave(); } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Unable to load leave requests." }); } finally { setLoadingKey(null); } }
  async function reviewLeave(request: AdminLeaveRequestRecord, status: "approved" | "rejected") {
    const key = `leave-${status}-${request._id}`; setLoadingKey(key); setNotice(null);
    try {
      const response = await fetch(`/api/attendance/admin/leave/${request._id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status, reviewNote: reviewNotes[request._id] ?? "" }) });
      const payload = (await response.json()) as ApiResponse;
      if (!response.ok || !payload.success) throw new Error(payload.error?.message ?? "Unable to review leave request.");
      await loadLeave(); setReviewNotes((current) => { const next = { ...current }; delete next[request._id]; return next; });
      setNotice({ tone: "success", text: status === "approved" ? "Leave request approved." : "Leave request rejected." });
    } catch (error) { setNotice({ tone: "error", text: error instanceof Error ? error.message : "Unable to review leave request." }); }
    finally { setLoadingKey(null); }
  }
  async function saveGeofence() {
    const officeLatitude = Number(geofenceForm.officeLatitude); const officeLongitude = Number(geofenceForm.officeLongitude); const officeRadiusMeters = Number(geofenceForm.officeRadiusMeters);
    if (!Number.isFinite(officeLatitude) || !Number.isFinite(officeLongitude) || !Number.isInteger(officeRadiusMeters)) { setNotice({ tone: "error", text: "Enter valid latitude, longitude, and radius." }); return; }
    await runAction("geofence-save", "/api/attendance/admin/settings", "PATCH", "Office location updated successfully.", { body: { officeLatitude, officeLongitude, officeRadiusMeters } });
  }
  async function saveLateRule() {
    const lateGraceMinutes = Number(lateRuleForm.lateGraceMinutes);
    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(lateRuleForm.shiftStartTime)) { setNotice({ tone: "error", text: "Enter a valid shift start time (HH:mm)." }); return; }
    if (!Number.isInteger(lateGraceMinutes) || lateGraceMinutes < 0 || lateGraceMinutes > 180) { setNotice({ tone: "error", text: "Grace period must be 0-180 minutes." }); return; }
    await runAction("late-rule-save", "/api/attendance/admin/settings/late-rule", "PATCH", "Late rule updated successfully.", { body: { shiftStartTime: lateRuleForm.shiftStartTime, lateGraceMinutes }, onSuccess: () => setLateRuleConfigured(true) });
  }
  async function saveAttendance() {
    await runAction("attendance-mark", "/api/attendance/admin/mark", "POST", "Attendance marked successfully.", { body: markForm, refreshDaily: true, refreshDate: markForm.dateKey, refreshMonthly: true, refreshMonth: markForm.dateKey.slice(0, 7), onSuccess: () => setMobileMarkOpen(false) });
  }

  const recordMap = useMemo(() => new Map(dailyRecords.flatMap((record) => record.userId?._id ? [[record.userId._id, record] as const] : [])), [dailyRecords]);
  const dailyRows = useMemo(() => staffUsers.map((user) => ({ user, record: recordMap.get(user._id) })), [staffUsers, recordMap]);
  const filteredDaily = useMemo(() => { const query = dailySearch.trim().toLowerCase(); return dailyRows.filter(({ user, record }) => (!query || `${user.fullName} ${user.email} ${user.role}`.toLowerCase().includes(query)) && (dailyStatus === "all" || (dailyStatus === "not_marked" ? !record : record?.dayStatus === dailyStatus))); }, [dailyRows, dailySearch, dailyStatus]);
  const presentCount = dailyRows.filter(({ record }) => record && record.dayStatus !== "absent").length;
  const notMarkedCount = dailyRows.filter(({ record }) => !record).length;
  const cancelledCount = leaveData.requests.filter((request) => request.status === "cancelled").length;
  const dates = useMemo(() => monthDates(monthlyData.monthKey), [monthlyData.monthKey]);
  const selectedMonthRow = monthlyData.rows.find((row) => row.user._id === selectedMonthlyUserId) ?? monthlyData.rows[0];
  const selectedDayRecord = selectedMonthRow?.records.find((record) => record.dateKey === selectedMonthDateKey);
  const filteredLeaves = useMemo(() => { const query = leaveSearch.trim().toLowerCase(); return leaveData.requests.filter((request) => (!query || `${request.userId?.fullName ?? ""} ${request.userId?.email ?? ""}`.toLowerCase().includes(query)) && (leaveStatus === "all" || request.status === leaveStatus) && (leaveType === "all" || request.leaveType === leaveType)); }, [leaveData.requests, leaveSearch, leaveStatus, leaveType]);
  const selectedLeave = filteredLeaves.find((request) => request._id === selectedLeaveId) ?? filteredLeaves[0];

  function openMark(userId: string, record?: AdminDailyAttendanceRecord) { setMarkForm({ userId, dateKey: record?.dateKey ?? dailyDateKey, dayStatus: record?.dayStatus ?? "present" }); setMobileMarkOpen(true); }
  function openOfficeSettings() {
    setActiveView("daily");
    setOfficeSettingsOpen(true);
    window.setTimeout(() => document.getElementById("attendance-office-settings")?.scrollIntoView({ behavior: "smooth", block: "center" }), 0);
  }
  function downloadCsv(filename: string, rows: Array<Array<string | number>>) {
    const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url);
  }
  function exportView() {
    const rows: Array<Array<string | number>> = activeView === "daily" ? [["Staff", "Status", "Check-in", "Check-out", "Work time", "Break"], ...dailyRows.map(({ user, record }) => [user.fullName, record?.dayStatus ?? "not_marked", timeLabel(record?.checkInAt), timeLabel(record?.checkOutAt), workLabel(record?.workedMinutes), record?.totalBreakMinutes ?? 0])] : activeView === "monthly" ? [["Staff", "Present", "Late", "Absent", "Half day", "Marked"], ...monthlyData.rows.map((row) => [row.user.fullName, row.summary.presentDays, row.summary.lateComingDays, row.summary.absentDays, row.summary.halfDays, row.summary.totalMarkedDays])] : [["Staff", "From", "To", "Type", "Days", "Status"], ...leaveData.requests.map((request) => [request.userId?.fullName ?? "Unknown", request.startDateKey, request.endDateKey, request.leaveType, request.totalDays, request.status])];
    downloadCsv(`attendance-${activeView}.csv`, rows);
  }
  // The regular monthly export above is one row per employee - totals only, no times. This is the
  // "full month report" version: one row per employee PER DAY of the month (every day, including
  // ones with no record at all, so a genuinely blank day is visible as blank rather than silently
  // missing from the report), with the actual check-in/check-out timestamps.
  function exportMonthlyDetail() {
    const rows: Array<Array<string | number>> = [["Date", "Staff", "Status", "Check-in", "Check-out", "Work time", "Break"]];
    for (const row of monthlyData.rows) {
      const recordsByDate = new Map(row.records.map((record) => [record.dateKey, record] as const));
      for (const dateKey of dates) {
        const record = recordsByDate.get(dateKey);
        const status = record?.dayStatus ?? (isWeekend(dateKey) ? "weekend_off" : "not_marked");
        rows.push([dateKey, row.user.fullName, titleCase(status === "weekend_off" ? "weekend" : status), timeLabel(record?.checkInAt), timeLabel(record?.checkOutAt), workLabel(record?.workedMinutes), record?.totalBreakMinutes ?? 0]);
      }
    }
    downloadCsv(`attendance-monthly-detail-${monthlyData.monthKey}.csv`, rows);
  }

  function renderDateNav(monthly = false) {
    const value = monthly ? monthKey : dailyDateKey;
    const move = (amount: number) => monthly ? void refreshMonth(shiftMonth(monthKey, amount)) : void refreshDaily(shiftDate(dailyDateKey, amount));
    return <div className="flex items-center gap-2"><button type="button" onClick={() => move(-1)} disabled={loadingKey !== null} className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-md border border-vega-border text-vega-text-secondary hover:bg-vega-surface-hover" aria-label="Previous"><ChevronLeft className="h-4 w-4" /></button><label className="relative flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md border border-vega-border bg-[#0b141f] px-3 text-xs font-medium text-vega-text sm:min-w-[220px]"><CalendarDays className="h-4 w-4 text-vega-text-muted" /><span className="truncate">{monthly ? monthLabel(value) : dateLabel(value, true)}</span><input className="absolute inset-0 cursor-pointer opacity-0" type={monthly ? "month" : "date"} value={value} onChange={(event) => monthly ? void refreshMonth(event.target.value) : void refreshDaily(event.target.value)} /></label><button type="button" onClick={() => move(1)} disabled={loadingKey !== null} className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-md border border-vega-border text-vega-text-secondary hover:bg-vega-surface-hover" aria-label="Next"><ChevronRight className="h-4 w-4" /></button><Button variant="secondary" className="hidden sm:inline-flex" onClick={() => monthly ? void refreshMonth(initialMonthKey) : void refreshDaily(initialDailyDateKey)}>{monthly ? "Current month" : "Today"}</Button></div>;
  }
  function renderMarkForm(dismiss = false) {
    return <div className="space-y-3 p-4"><div className="flex items-start gap-3"><span className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-vega-accent-soft text-vega-accent"><FileText className="h-4 w-4" /></span><div><h3 className="text-sm font-semibold text-vega-text">Mark attendance</h3><p className="text-[11px] text-vega-text-muted">Add or update a daily record.</p></div>{dismiss ? <button type="button" className="ml-auto text-vega-text-muted" onClick={() => setMobileMarkOpen(false)} aria-label="Close"><X className="h-4 w-4" /></button> : null}</div><label className="block text-[11px] text-vega-text-muted">Staff<select className={cn(select, "mt-1")} value={markForm.userId} onChange={(event) => setMarkForm((current) => ({ ...current, userId: event.target.value }))}>{staffUsers.map((user) => <option key={user._id} value={user._id}>{user.fullName}</option>)}</select></label><div className="grid grid-cols-2 gap-3"><label className="text-[11px] text-vega-text-muted">Date<Input type="date" className="mt-1 h-[38px]" value={markForm.dateKey} onChange={(event) => setMarkForm((current) => ({ ...current, dateKey: event.target.value }))} /></label><label className="text-[11px] text-vega-text-muted">Status<select className={cn(select, "mt-1")} value={markForm.dayStatus} onChange={(event) => setMarkForm((current) => ({ ...current, dayStatus: event.target.value as AttendanceDayStatus }))}><option value="present">Present</option><option value="late_coming">Late coming</option><option value="absent">Absent</option><option value="half_day">Half day</option></select></label></div><Button className="w-full" onClick={() => void saveAttendance()} disabled={!markForm.userId || !markForm.dateKey || loadingKey !== null}>{loadingKey === "attendance-mark" ? "Saving..." : "Save attendance"}</Button></div>;
  }
  function renderLateRule(editable = true) {
    return <div className={cn(panel, "p-4")} id="attendance-late-rule-settings"><div className="flex items-start gap-3"><span className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-vega-accent-soft text-[#f0b429]"><Clock3 className="h-5 w-5" /></span><div className="min-w-0 flex-1"><h3 className="text-sm font-semibold text-vega-text">Late rule</h3><p className="text-[11px] text-vega-text-muted">Check-in after shift start + grace auto-marks Late coming.</p><p className="mt-0.5 text-[10px] text-vega-text-dim">{lateRuleConfigured ? "Applies to check-ins from now on - past days are unaffected." : "Not configured - every check-in is marked Present regardless of time."}</p></div>{!editable ? <Button variant="secondary" onClick={() => setLateRuleSettingsOpen(true)}><Settings className="mr-2 h-4 w-4" />Manage</Button> : null}</div>{editable || lateRuleSettingsOpen ? <div className="mt-4 space-y-3"><div className="grid grid-cols-2 gap-3"><label className="text-[10px] text-vega-text-muted">Shift start<Input type="time" className="mt-1" value={lateRuleForm.shiftStartTime} onChange={(event) => setLateRuleForm((current) => ({ ...current, shiftStartTime: event.target.value }))} /></label><label className="text-[10px] text-vega-text-muted">Grace (minutes)<Input inputMode="numeric" className="mt-1" value={lateRuleForm.lateGraceMinutes} onChange={(event) => setLateRuleForm((current) => ({ ...current, lateGraceMinutes: event.target.value }))} /></label></div><Button variant="secondary" className="w-full text-[#a8c8ff]" onClick={() => void saveLateRule()} disabled={loadingKey !== null}>{loadingKey === "late-rule-save" ? "Saving..." : "Save late rule"}</Button></div> : null}</div>;
  }
  function renderOfficeLocation(editable = true) {
    return <div className={cn(panel, "p-4")} id="attendance-office-settings"><div className="flex items-start gap-3"><span className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-vega-accent-soft text-[#ad7aff]"><MapPin className="h-5 w-5" /></span><div className="min-w-0 flex-1"><h3 className="text-sm font-semibold text-vega-text">Office location</h3><p className="text-[11px] text-vega-text-muted">Check-in is allowed inside this office radius.</p><p className="mt-0.5 text-[10px] text-vega-text-dim">Check-out does not use geofencing.</p></div>{!editable ? <Button variant="secondary" onClick={() => setOfficeSettingsOpen(true)}><Settings className="mr-2 h-4 w-4" />Manage</Button> : null}</div>{editable || officeSettingsOpen ? <div className="mt-4 space-y-3"><div className="grid grid-cols-2 gap-3"><label className="text-[10px] text-vega-text-muted">Latitude<Input inputMode="decimal" className="mt-1" value={geofenceForm.officeLatitude} onChange={(event) => setGeofenceForm((current) => ({ ...current, officeLatitude: event.target.value }))} /></label><label className="text-[10px] text-vega-text-muted">Longitude<Input inputMode="decimal" className="mt-1" value={geofenceForm.officeLongitude} onChange={(event) => setGeofenceForm((current) => ({ ...current, officeLongitude: event.target.value }))} /></label></div><label className="text-[10px] text-vega-text-muted">Allowed radius (metres)<Input inputMode="numeric" className="mt-1" value={geofenceForm.officeRadiusMeters} onChange={(event) => setGeofenceForm((current) => ({ ...current, officeRadiusMeters: event.target.value }))} /></label><Button variant="secondary" className="w-full text-[#a8c8ff]" onClick={() => void saveGeofence()} disabled={loadingKey !== null}>{loadingKey === "geofence-save" ? "Saving..." : "Save location"}</Button></div> : null}</div>;
  }

  return <section className="min-w-0">
    <div className="mb-3 flex items-start justify-between gap-3"><div><h1 className="text-[26px] font-semibold leading-8 text-vega-text lg:text-[28px]">Attendance</h1><p className="mt-0.5 text-xs text-vega-text-muted lg:text-sm">Manage your team&apos;s time and leave.</p></div><div className="flex gap-2"><Button variant="secondary" size="lg" onClick={openOfficeSettings}><Settings className="mr-2 h-4 w-4" />Office settings</Button><Button size="lg" className="hidden lg:inline-flex" onClick={exportView}><Download className="mr-2 h-4 w-4" />Export</Button>{activeView === "monthly" ? <Button variant="secondary" size="lg" className="hidden lg:inline-flex" onClick={exportMonthlyDetail}><FileText className="mr-2 h-4 w-4" />Full report</Button> : null}</div></div>
    <div className="mb-4 grid h-10 grid-cols-3 overflow-hidden rounded-md border border-vega-border lg:w-[390px]">{(["daily", "monthly", "leave"] as AttendanceView[]).map((view) => <button key={view} type="button" onClick={() => setActiveView(view)} className={cn("border-r border-vega-border px-2 text-xs font-medium capitalize text-vega-text-secondary last:border-r-0", activeView === view && "bg-vega-accent text-white")}>{view === "leave" ? "Leave requests" : view}</button>)}</div>
    {notice ? <div className={cn("mb-3 rounded-md border px-3 py-2 text-xs", notice.tone === "error" ? "border-vega-red/40 bg-vega-red-soft text-[#ff838b]" : "border-vega-green/35 bg-vega-green-soft text-[#6ce39a]")}>{notice.text}</div> : null}

    {activeView === "daily" ? <div className="space-y-4">{renderDateNav()}<div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={UsersRound} label="Total staff" value={staffUsers.length} /><Metric icon={UserRound} label="Present" value={presentCount} tone="green" /><Metric icon={CircleMinus} label="Not marked" value={notMarkedCount} tone="neutral" /><Metric icon={FileText} label="Pending leave" value={leaveData.summary.pendingCount} tone="purple" /></div><div className="grid items-start gap-4 xl:grid-cols-[minmax(0,1fr)_330px]"><div className={panel}><div className="flex flex-col gap-3 border-b border-vega-border px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center justify-between"><h2 className="text-base font-semibold text-vega-text">Daily attendance</h2><span className="text-xs text-vega-text-muted sm:hidden">{staffUsers.length} staff</span></div><div className="flex gap-2"><label className="relative min-w-0 flex-1 sm:w-56"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-vega-text-muted" /><Input placeholder="Search staff..." value={dailySearch} onChange={(event) => setDailySearch(event.target.value)} className="h-[38px] pl-9" /></label><select aria-label="Filter attendance status" className={cn(select, "hidden w-40 sm:block")} value={dailyStatus} onChange={(event) => setDailyStatus(event.target.value)}><option value="all">All statuses</option><option value="present">Present</option><option value="late_coming">Late</option><option value="absent">Absent</option><option value="half_day">Half day</option><option value="not_marked">Not marked</option></select><button type="button" onClick={() => setDailyStatus((current) => current === "all" ? "not_marked" : "all")} className="inline-flex h-[38px] w-[38px] items-center justify-center rounded-md border border-vega-border text-vega-text-secondary sm:hidden" aria-label="Filter staff"><Filter className="h-4 w-4" /></button></div></div>
      <div className="hidden overflow-x-auto lg:block"><table className="w-full min-w-[760px] table-fixed text-left text-xs"><thead className="bg-[#0b151f] text-[11px] text-vega-text-muted"><tr><th className="w-[28%] px-4 py-2.5 font-medium">Staff</th><th className="px-3 py-2.5 font-medium">Status</th><th className="px-3 py-2.5 font-medium">Check-in</th><th className="px-3 py-2.5 font-medium">Check-out</th><th className="px-3 py-2.5 font-medium">Work time</th><th className="px-3 py-2.5 font-medium">Break</th><th className="w-16 px-3 py-2.5 font-medium">Action</th></tr></thead><tbody>{filteredDaily.map(({ user, record }, index) => { const badge = attendanceBadge(record?.dayStatus); return <tr key={user._id} className="border-t border-vega-border-soft hover:bg-vega-surface-hover/50"><td className="px-4 py-2.5"><div className="flex items-center gap-2.5"><Avatar name={user.fullName} index={index} /><div className="min-w-0"><p className="truncate font-medium text-vega-text">{user.fullName}</p><p className="truncate text-[10px] capitalize text-vega-text-muted">{user.role.replaceAll("_", " ")}</p></div></div></td><td className="px-3 py-2.5"><Badge variant={badge.variant}>{badge.label}</Badge></td><td className="px-3 py-2.5 text-vega-text-secondary">{timeLabel(record?.checkInAt)}</td><td className="px-3 py-2.5 text-vega-text-secondary">{timeLabel(record?.checkOutAt)}</td><td className="px-3 py-2.5 text-vega-text-secondary">{record?.checkInAt && !record.checkOutAt ? "In progress" : workLabel(record?.workedMinutes)}</td><td className="px-3 py-2.5 text-vega-text-secondary">{record ? `${record.totalBreakMinutes ?? 0}m` : "--"}</td><td className="px-3 py-2.5"><button type="button" onClick={() => openMark(user._id, record)} className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-vega-border text-vega-text-secondary" aria-label={`Edit ${user.fullName}`}><Pencil className="h-3.5 w-3.5" /></button></td></tr>; })}</tbody></table></div>
      <div className="space-y-2.5 p-3 lg:hidden">{filteredDaily.filter(({ record }) => Boolean(record)).map(({ user, record }, index) => { const badge = attendanceBadge(record?.dayStatus); return <div key={user._id} className="rounded-md border border-vega-border bg-[#0b151f] p-3"><div className="flex items-center gap-3"><Avatar name={user.fullName} index={index} /><p className="min-w-0 flex-1 truncate text-sm font-semibold text-vega-text">{user.fullName}</p><Badge variant={badge.variant} className="h-7 px-3 text-[11px]">{badge.label}</Badge><button type="button" onClick={() => openMark(user._id, record)} className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-vega-border text-vega-text-secondary" aria-label={`Edit ${user.fullName}`}><Pencil className="h-4 w-4" /></button></div><div className="mt-3 grid grid-cols-2 border-t border-vega-border-soft pt-3 text-xs"><div className="space-y-1"><p><span className="inline-block w-[72px] text-vega-text-muted">Check-in</span>{timeLabel(record?.checkInAt)}</p><p><span className="inline-block w-[72px] text-vega-text-muted">Work time</span>{record?.checkInAt && !record.checkOutAt ? "In progress" : workLabel(record?.workedMinutes)}</p></div><div className="space-y-1 border-l border-vega-border pl-3"><p><span className="inline-block w-[70px] text-vega-text-muted">Check-out</span>{timeLabel(record?.checkOutAt)}</p><p><span className="inline-block w-[70px] text-vega-text-muted">Break</span>{record?.totalBreakMinutes ?? 0}m</p></div></div></div>; })}{filteredDaily.some(({ record }) => !record) ? <div><h3 className="mb-2 text-sm font-semibold text-vega-text">Not marked <span className="text-vega-text-muted">- {filteredDaily.filter(({ record }) => !record).length}</span></h3><div className="overflow-hidden rounded-md border border-vega-border">{filteredDaily.filter(({ record }) => !record).map(({ user }, index) => <div key={user._id} className="flex items-center gap-3 border-b border-vega-border-soft px-3 py-2.5 last:border-b-0"><Avatar name={user.fullName} index={index + 2} /><p className="min-w-0 flex-1 truncate text-sm font-medium text-vega-text">{user.fullName}</p><Badge variant="neutral">Not marked</Badge><button type="button" onClick={() => openMark(user._id)} className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-vega-border text-vega-text-secondary" aria-label={`Mark ${user.fullName}`}><Pencil className="h-3.5 w-3.5" /></button></div>)}</div></div> : null}</div><div className="hidden items-center justify-between border-t border-vega-border px-4 py-2.5 text-[11px] text-vega-text-muted lg:flex"><span>Showing {filteredDaily.length} staff</span><button type="button" onClick={() => void refreshDaily()} disabled={loadingKey !== null} className="inline-flex items-center gap-2"><RefreshCw className={cn("h-3.5 w-3.5", loadingKey === "daily-refresh" && "animate-spin")} />Refresh</button></div></div><aside className="hidden space-y-3 xl:block"><div className={panel}>{renderMarkForm()}</div>{renderOfficeLocation()}{renderLateRule()}</aside></div><div className="space-y-3 xl:hidden">{renderOfficeLocation(false)}{renderLateRule(false)}</div><button type="button" onClick={() => setMobileMarkOpen(true)} className="sticky bottom-3 z-20 flex h-12 w-full items-center justify-center gap-2 rounded-md bg-vega-accent text-sm font-semibold text-white shadow-[0_8px_28px_rgba(90,45,220,0.35)] lg:hidden"><span className="text-xl">+</span>Mark attendance</button></div> : null}

    {activeView === "monthly" ? <div className="space-y-4">{renderDateNav(true)}<div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={UsersRound} label="Staff" value={monthlyData.totals.staffCount} /><Metric icon={FileText} label="Marked entries" value={monthlyData.totals.totalMarkedDays} tone="neutral" /><Metric icon={UserRound} label="Present" value={monthlyData.totals.presentDays} tone="green" /><Metric icon={Clock3} label="Late" value={monthlyData.totals.lateComingDays} tone="purple" /></div>
      <div className={cn(panel, "hidden overflow-hidden lg:block")}><div className="flex items-center justify-between border-b border-vega-border px-4 py-3"><h2 className="text-base font-semibold text-vega-text">Team attendance</h2><button type="button" onClick={() => void refreshMonth()} className="inline-flex items-center gap-2 text-xs text-vega-text-muted"><RefreshCw className={cn("h-3.5 w-3.5", loadingKey === "month-refresh" && "animate-spin")} />Refresh</button></div><div className="overflow-x-auto"><table className="min-w-max border-collapse text-center text-[11px]"><thead><tr className="bg-[#0b151f] text-vega-text-muted"><th className="sticky left-0 z-10 min-w-[290px] border-r border-vega-border bg-[#0b151f] px-3 py-2 text-left font-medium">Staff</th>{dates.map((key) => <th key={key} className={cn("h-9 w-10 border-r border-vega-border-soft font-medium", key === selectedMonthDateKey && "bg-vega-accent-soft text-[#93c5fd]")}>{key.slice(-2)}</th>)}<th className="w-10">P</th><th className="w-10">L</th><th className="w-10">A</th></tr></thead><tbody>{monthlyData.rows.map((row, index) => { const records = new Map(row.records.map((record) => [record.dateKey, record] as const)); const status = monthlyStatusBadge(row.summary); return <tr key={row.user._id} className="border-t border-vega-border-soft"><td className="sticky left-0 z-10 border-r border-vega-border bg-vega-surface-1 px-3 py-2 text-left"><div className="flex items-center gap-2"><Avatar name={row.user.fullName} index={index} /><span className="min-w-0 flex-1 truncate font-medium text-vega-text">{row.user.fullName}</span><Badge variant={status.variant} className="shrink-0 whitespace-nowrap text-[10px]">{status.label}</Badge><a href={`/api/attendance/admin/month/${row.user._id}/pdf?month=${monthlyData.monthKey}`} download className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded text-vega-text-secondary hover:bg-vega-surface-hover hover:text-vega-accent" aria-label={`Download ${row.user.fullName}'s attendance PDF for ${monthLabel(monthlyData.monthKey)}`} title="Download PDF"><Download className="h-3.5 w-3.5" /></a></div></td>{dates.map((key) => { const raw = records.get(key)?.dayStatus; const cellStatus = raw ?? (isWeekend(key) ? "weekend_off" : undefined); return <td key={key} className={cn("h-10 border-r border-vega-border-soft", key === selectedMonthDateKey && "bg-vega-accent-soft/60")}><button type="button" onClick={() => { setSelectedMonthlyUserId(row.user._id); setSelectedMonthDateKey(key); }} className={cn("mx-auto inline-flex h-7 w-7 items-center justify-center rounded font-semibold", statusClass(cellStatus), selectedMonthlyUserId === row.user._id && selectedMonthDateKey === key && "ring-2 ring-vega-accent")}>{statusSymbol(cellStatus)}</button></td>; })}<td className="font-semibold">{row.summary.presentDays}</td><td className="font-semibold">{row.summary.lateComingDays}</td><td className="font-semibold">{row.summary.absentDays}</td></tr>; })}</tbody></table></div><div className="flex flex-wrap items-center gap-5 border-t border-vega-border px-4 py-3 text-[11px] text-vega-text-muted">{(["present", "late_coming", "absent", "half_day", "weekend_off", undefined] as Array<GridStatus | undefined>).map((status) => <span key={status ?? "empty"} className="inline-flex items-center gap-2"><span className={cn("inline-flex h-6 w-6 items-center justify-center rounded font-semibold", statusClass(status))}>{statusSymbol(status)}</span>{status ? titleCase(status === "weekend_off" ? "weekend" : status) : "Not marked"}</span>)}</div></div>
    {/* Desktop had no way to see a selected cell's actual check-in/check-out time - the grid only
        ever showed the P/L/A/W letter. Click any day in the table above to populate this. Mobile
        already has its own copy of this same card further down (inside the lg:hidden block), so
        this is gated to lg+ only to avoid showing it twice on a phone. */}
    {selectedMonthRow ? <div className={cn(panel, "hidden p-4 lg:block")}><div className="mb-3 flex items-center gap-2 border-b border-vega-border-soft pb-3"><Avatar name={selectedMonthRow.user.fullName} index={monthlyData.rows.findIndex((row) => row.user._id === selectedMonthRow.user._id)} /><span className="text-sm font-medium text-vega-text">{selectedMonthRow.user.fullName}</span></div><div className="flex items-center justify-between"><h3 className="text-base font-semibold">{Number(selectedMonthDateKey.slice(-2))} {monthLabel(monthlyData.monthKey).split(" ")[0]} <span className="text-vega-text-muted">-</span> <span className={selectedDayRecord?.dayStatus === "present" ? "text-[#62df91]" : "text-vega-text-muted"}>{selectedDayRecord ? titleCase(selectedDayRecord.dayStatus) : "Not marked"}</span></h3>{selectedDayRecord ? <button type="button" onClick={() => openMark(selectedMonthRow.user._id, { ...selectedDayRecord, userId: selectedMonthRow.user } as AdminDailyAttendanceRecord)} className="text-xs font-medium text-vega-accent">Edit record</button> : null}</div><div className="mt-4 grid grid-cols-3 divide-x divide-vega-border text-xs"><div><p className="text-vega-text-muted">Check-in</p><p className="mt-1 text-sm">{timeLabel(selectedDayRecord?.checkInAt)}</p></div><div className="pl-3"><p className="text-vega-text-muted">Check-out</p><p className="mt-1 text-sm">{timeLabel(selectedDayRecord?.checkOutAt)}</p></div><div className="pl-3"><p className="text-vega-text-muted">Work time</p><p className="mt-1 text-sm">{selectedDayRecord?.checkInAt && !selectedDayRecord.checkOutAt ? "In progress" : workLabel(selectedDayRecord?.workedMinutes)}</p></div></div></div> : null}
      {selectedMonthRow ? <div className="space-y-3 lg:hidden"><label className={cn(panel, "relative flex items-center gap-3 p-3")}><Avatar name={selectedMonthRow.user.fullName} large /><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate text-sm font-semibold text-vega-text">{selectedMonthRow.user.fullName}</p><Badge variant={monthlyStatusBadge(selectedMonthRow.summary).variant} className="shrink-0 text-[10px]">{monthlyStatusBadge(selectedMonthRow.summary).label}</Badge></div><p className="mt-1 text-xs text-vega-text-muted">{selectedMonthRow.summary.presentDays} Present - {selectedMonthRow.summary.lateComingDays} Late - {selectedMonthRow.summary.absentDays} Absent</p></div><ChevronDown className="h-4 w-4 text-vega-text-muted" /><select className="absolute inset-0 opacity-0" value={selectedMonthRow.user._id} onChange={(event) => setSelectedMonthlyUserId(event.target.value)}>{monthlyData.rows.map((row) => <option key={row.user._id} value={row.user._id}>{row.user.fullName}</option>)}</select></label><div className={cn(panel, "overflow-hidden")}><div className="grid grid-cols-7 border-b border-vega-border bg-[#0b151f] text-center text-[11px] text-vega-text-muted">{["M", "T", "W", "T", "F", "S", "S"].map((day, index) => <span key={`${day}-${index}`} className="py-2.5">{day}</span>)}</div><div className="grid grid-cols-7">{Array.from({ length: (parseDate(`${monthlyData.monthKey}-01`).getDay() + 6) % 7 }).map((_, index) => <span key={`blank-${index}`} className="h-[60px] border-b border-r border-vega-border-soft" />)}{dates.map((key) => { const raw = selectedMonthRow.records.find((record) => record.dateKey === key)?.dayStatus; const status = raw ?? (isWeekend(key) ? "weekend_off" : undefined); return <button key={key} type="button" onClick={() => setSelectedMonthDateKey(key)} className={cn("flex h-[60px] flex-col items-center justify-center gap-1 border-b border-r border-vega-border-soft text-sm", selectedMonthDateKey === key && "bg-vega-accent-soft ring-2 ring-inset ring-vega-accent")}><span>{Number(key.slice(-2))}</span><span className={cn("text-xs font-semibold", statusClass(status).replace(/bg-\S+\s?/, ""))}>{statusSymbol(status)}</span></button>; })}</div></div><div className="flex flex-wrap gap-4 px-2 text-[11px] text-vega-text-muted">{(["present", "late_coming", "weekend_off", undefined] as Array<GridStatus | undefined>).map((status) => <span key={status ?? "none"} className="inline-flex items-center gap-1.5"><span className={cn("inline-flex h-6 w-6 items-center justify-center rounded font-semibold", statusClass(status))}>{statusSymbol(status)}</span>{status ? titleCase(status === "weekend_off" ? "weekend" : status) : "Not marked"}</span>)}</div><div className={cn(panel, "p-4")}><div className="flex items-center justify-between"><h3 className="text-base font-semibold">{Number(selectedMonthDateKey.slice(-2))} {monthLabel(monthlyData.monthKey).split(" ")[0]} <span className="text-vega-text-muted">-</span> <span className={selectedDayRecord?.dayStatus === "present" ? "text-[#62df91]" : "text-vega-text-muted"}>{selectedDayRecord ? titleCase(selectedDayRecord.dayStatus) : "Not marked"}</span></h3>{selectedDayRecord ? <button type="button" onClick={() => openMark(selectedMonthRow.user._id, { ...selectedDayRecord, userId: selectedMonthRow.user } as AdminDailyAttendanceRecord)} className="text-xs font-medium text-vega-accent">Edit record</button> : null}</div><div className="mt-4 grid grid-cols-3 divide-x divide-vega-border text-xs"><div><p className="text-vega-text-muted">Check-in</p><p className="mt-1 text-sm">{timeLabel(selectedDayRecord?.checkInAt)}</p></div><div className="pl-3"><p className="text-vega-text-muted">Check-out</p><p className="mt-1 text-sm">{timeLabel(selectedDayRecord?.checkOutAt)}</p></div><div className="pl-3"><p className="text-vega-text-muted">Work time</p><p className="mt-1 text-sm">{selectedDayRecord?.checkInAt && !selectedDayRecord.checkOutAt ? "In progress" : workLabel(selectedDayRecord?.workedMinutes)}</p></div></div></div><div className={cn(panel, "overflow-hidden")}><div className="flex items-center justify-between border-b border-vega-border px-4 py-3"><h3 className="text-sm font-semibold">Team summary <span className="font-normal text-vega-text-muted">(other staff)</span></h3><span className="text-xs text-vega-accent">View full team</span></div>{monthlyData.rows.filter((row) => row.user._id !== selectedMonthRow.user._id).map((row, index) => { const status = monthlyStatusBadge(row.summary); return <button key={row.user._id} type="button" onClick={() => setSelectedMonthlyUserId(row.user._id)} className="flex w-full items-center gap-3 border-b border-vega-border-soft px-4 py-2.5 text-left last:border-b-0"><Avatar name={row.user.fullName} index={index + 1} /><span className="min-w-0 flex-1 truncate text-sm">{row.user.fullName}</span><Badge variant={status.variant} className="shrink-0 whitespace-nowrap text-[10px]">{status.label}</Badge><ChevronRight className="h-4 w-4 text-vega-text-muted" /></button>; })}</div></div> : null}</div> : null}

    {activeView === "leave" ? <div className="space-y-4"><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric icon={Clock3} label="Pending" value={leaveData.summary.pendingCount} /><Metric icon={Check} label="Approved" value={leaveData.summary.approvedCount} tone="green" /><Metric icon={X} label="Rejected" value={leaveData.summary.rejectedCount} tone="red" /><Metric icon={CircleMinus} label="Cancelled" value={cancelledCount} tone="neutral" /></div>{leaveData.summary.pendingCount === 0 ? <div className="flex items-center gap-3 rounded-md border border-vega-green/35 bg-vega-green-soft px-4 py-3"><span className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#5ce58d] text-[#062414]"><Check className="h-4 w-4" /></span><div><p className="text-sm font-semibold text-[#73e7a0]">No pending requests</p><p className="text-[11px] text-vega-text-muted">All requests have been reviewed or closed.</p></div></div> : null}<div className="flex flex-col gap-2 sm:flex-row"><label className="relative min-w-0 flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-vega-text-muted" /><Input placeholder="Search staff..." className="h-[38px] pl-9" value={leaveSearch} onChange={(event) => setLeaveSearch(event.target.value)} /></label><select className={cn(select, "sm:w-40")} value={leaveStatus} onChange={(event) => setLeaveStatus(event.target.value)}><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="cancelled">Cancelled</option></select><select className={cn(select, "sm:w-36")} value={leaveType} onChange={(event) => setLeaveType(event.target.value)}><option value="all">All types</option><option value="planned">Planned</option><option value="casual">Casual</option><option value="sick">Sick</option><option value="unpaid">Unpaid</option><option value="other">Other</option></select><button type="button" onClick={() => void refreshLeave()} className="hidden h-[38px] w-[38px] items-center justify-center rounded-md border border-vega-border text-vega-text-secondary sm:inline-flex" aria-label="Refresh"><RefreshCw className={cn("h-4 w-4", loadingKey === "leave-refresh" && "animate-spin")} /></button></div><div className="grid items-start gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
      <div className={cn(panel, "hidden overflow-hidden lg:block")}><div className="flex items-center gap-2 border-b border-vega-border px-4 py-3"><h2 className="text-base font-semibold">Leave requests</h2><span className="text-xs text-vega-text-muted">{filteredLeaves.length} requests</span></div><table className="w-full table-fixed text-left text-xs"><thead className="bg-[#0b151f] text-[11px] text-vega-text-muted"><tr><th className="w-[27%] px-4 py-2.5 font-medium">Staff</th><th className="w-[28%] px-3 py-2.5 font-medium">Leave dates</th><th className="px-3 py-2.5 font-medium">Type</th><th className="px-3 py-2.5 font-medium">Status</th><th className="w-20 px-3 py-2.5 font-medium">Action</th></tr></thead><tbody>{filteredLeaves.map((request, index) => { const badge = leaveBadge(request.status); const name = request.userId?.fullName ?? "Unknown staff"; return <tr key={request._id} onClick={() => setSelectedLeaveId(request._id)} className={cn("cursor-pointer border-t border-vega-border-soft hover:bg-vega-surface-hover", selectedLeave?._id === request._id && "bg-vega-accent-soft")}><td className="px-4 py-2"><div className="flex items-center gap-2.5"><Avatar name={name} index={index} /><span className="truncate font-medium">{name}</span></div></td><td className="px-3 py-2 text-vega-text-secondary">{shortDate(request.startDateKey)}{request.endDateKey !== request.startDateKey ? ` - ${shortDate(request.endDateKey)}` : ""}</td><td className="px-3 py-2 capitalize text-vega-text-secondary">{request.leaveType}</td><td className="px-3 py-2"><Badge variant={badge.variant}>{badge.label}</Badge></td><td className="px-3 py-2 text-vega-accent">View <ChevronRight className="inline h-3.5 w-3.5" /></td></tr>; })}</tbody></table><div className="border-t border-vega-border px-4 py-2.5 text-[11px] text-vega-text-muted">Showing {filteredLeaves.length} requests</div></div>
      <div className="space-y-3 lg:hidden"><div className="flex items-center justify-between"><h2 className="text-lg font-semibold">Recent requests</h2><span className="text-xs text-vega-text-muted">{filteredLeaves.length} total</span></div>{filteredLeaves.slice(0, visibleLeaveCount).map((request, index) => { const badge = leaveBadge(request.status); const name = request.userId?.fullName ?? "Unknown staff"; return <div key={request._id} className={cn(panel, "p-3")}><button type="button" onClick={() => setSelectedLeaveId(selectedLeaveId === request._id ? "" : request._id)} className="w-full text-left"><div className="flex items-center gap-3"><Avatar name={name} index={index} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{name}</p><p className="mt-0.5 text-xs capitalize text-vega-text-muted">{request.leaveType} leave</p></div><Badge variant={badge.variant} className="h-7 px-3 text-[11px]">{badge.label}</Badge></div><div className="mt-3 flex items-center gap-4 border-t border-vega-border-soft pt-3 text-xs text-vega-text-secondary"><span className="inline-flex items-center gap-2"><CalendarDays className="h-4 w-4 text-vega-text-muted" />{shortDate(request.startDateKey)}</span><span className="inline-flex items-center gap-2"><Clock3 className="h-4 w-4 text-vega-text-muted" />{request.totalDays} {request.totalDays === 1 ? "day" : "days"}</span><span className="ml-auto font-medium text-vega-accent">View <ChevronRight className="inline h-3.5 w-3.5" /></span></div></button>{selectedLeaveId === request._id && request.status === "pending" ? <div className="mt-3 space-y-2 border-t border-vega-border pt-3"><Input placeholder="Review note (optional)" value={reviewNotes[request._id] ?? ""} onChange={(event) => setReviewNotes((current) => ({ ...current, [request._id]: event.target.value }))} /><div className="grid grid-cols-2 gap-2"><Button onClick={() => void reviewLeave(request, "approved")}>Approve</Button><Button variant="danger" onClick={() => void reviewLeave(request, "rejected")}>Reject</Button></div></div> : null}</div>; })}{visibleLeaveCount < filteredLeaves.length ? <Button variant="subtle" className="w-full" size="lg" onClick={() => setVisibleLeaveCount((count) => count + 4)}>Load more requests</Button> : null}</div>
      {selectedLeave ? <aside className={cn(panel, "hidden p-4 lg:block")}><h2 className="text-base font-semibold">Request details</h2><div className="mt-4 flex items-center gap-3"><Avatar name={selectedLeave.userId?.fullName ?? "Unknown"} large /><div><p className="text-sm font-semibold">{selectedLeave.userId?.fullName ?? "Unknown staff"}</p><Badge variant={leaveBadge(selectedLeave.status).variant} className="mt-1">{leaveBadge(selectedLeave.status).label}</Badge></div></div><dl className="mt-5 grid grid-cols-2 gap-y-3 text-xs"><dt className="text-vega-text-muted">Type</dt><dd className="capitalize">{selectedLeave.leaveType}</dd><dt className="text-vega-text-muted">From</dt><dd>{shortDate(selectedLeave.startDateKey)}</dd><dt className="text-vega-text-muted">To</dt><dd>{shortDate(selectedLeave.endDateKey)}</dd><dt className="text-vega-text-muted">Duration</dt><dd>{selectedLeave.totalDays} {selectedLeave.totalDays === 1 ? "day" : "days"}</dd></dl><div className="mt-4 border-t border-vega-border pt-4"><p className="text-xs text-vega-text-muted">Reason</p><p className="mt-1 text-xs text-vega-text-secondary">{selectedLeave.reason || "No reason provided"}</p></div>{selectedLeave.status === "pending" ? <div className="mt-4 space-y-2 border-t border-vega-border pt-4"><Textarea placeholder="Review note (optional)" value={reviewNotes[selectedLeave._id] ?? ""} onChange={(event) => setReviewNotes((current) => ({ ...current, [selectedLeave._id]: event.target.value }))} className="min-h-20" /><div className="grid grid-cols-2 gap-2"><Button onClick={() => void reviewLeave(selectedLeave, "approved")} disabled={loadingKey !== null}>Approve</Button><Button variant="danger" onClick={() => void reviewLeave(selectedLeave, "rejected")} disabled={loadingKey !== null}>Reject</Button></div></div> : null}</aside> : null}</div></div> : null}
    {mobileMarkOpen ? <div className="fixed inset-0 z-50 flex items-end bg-black/65 p-3 lg:hidden" role="dialog" aria-modal="true" aria-label="Mark attendance"><div className={cn(panel, "w-full bg-[#0a141f]")}>{renderMarkForm(true)}</div></div> : null}
  </section>;
}
